const pages = [
  { href: "index.html", label: "Home" },
  { href: "menu.html", label: "Menu" },
  { href: "about.html", label: "About" },
  { href: "contact.html", label: "Contact" },
]
// In a real site: const here = location.pathname.split("/").pop() || "index.html"
const here = "menu.html"

// 1. Build the nav from `pages`: one <a href=...>label</a> per page, inside <nav>, put into #site-header
// 2. The link for `here` gets aria-current="page" (and only that one)
// 3. #site-footer shows: "Open Mon–Sat 8am–9pm · © <this year> Mama Put Kitchen"
// 4. Log how many links the nav has

const links = pages
  .map((p) => `<a href="${p.href}"${p.href === here ? ' aria-current="page"' : ""}>${p.label}</a>`)
  .join("")
document.querySelector("#site-header").innerHTML = `<nav>${links}</nav>`
document.querySelector("#site-footer").textContent = `Open Mon–Sat 8am–9pm · © ${new Date().getFullYear()} Mama Put Kitchen`
console.log(document.querySelectorAll("nav a").length)
